const techOutput = z.object({ signals: z.array(z.object({ technology: str, changeType: z.enum(['adopción', 'migración', 'abandono', 'evaluación', 'desconocido']), observedAt: isoDate, evidence: z.array(sourceRef).min(1), confidence, commercialImplication: str })), confirmedStack: z.array(z.object({ technology: str, evidence: z.array(sourceRef).min(1) })), unknowns: z.array(str), suggestedOutreach: str })
defineStructuredMicroapp({ id: 'technology-change-detector', name: 'Detector de cambio tecnológico', promise: 'Detecta adopciones, migraciones y evaluaciones tecnológicas con evidencia pública actual', category: 'research', inputSchema: techInput, outputSchema: techOutput, capabilities: ['web.search','llm.generate'], freshnessDays: 3,
  uiSchema: [field('company','Empresa','text'), field('companyDomain','Web','url'), field('technologiesOfInterest','Tecnologías'), field('lookbackDays','Periodo','number')], followUps: [{ kind:'create_account_signal', label:'Guardar señal en la cuenta' }],
  costItems: i => webCost(`"${i.company}" site:${new URL(i.companyDomain).hostname} (${i.technologiesOfInterest.join(' OR ')}) migration OR implementation OR hiring`, i, i.lookbackDays), prepare: (ctx,i) => research(ctx, `"${i.company}" site:${new URL(i.companyDomain).hostname} (${i.technologiesOfInterest.join(' OR ')}) migration OR implementation OR hiring`, i.lookbackDays),
  system: () => system('Eres analista de inteligencia tecnológica.', '{"signals":[{"technology":"","changeType":"adopción|migración|abandono|evaluación|desconocido","observedAt":"","evidence":[{"sourceNumber":1,"claim":""}],"confidence":"alta|media|baja","commercialImplication":""}],"confirmedStack":[{"technology":"","evidence":[{"sourceNumber":1,"claim":""}]}],"unknowns":[],"suggestedOutreach":""}', 'Una tecnología solo puede figurar como confirmada si la fuente lo dice explícitamente. Las vacantes son señales, no confirmación.'), prompt: payload, finalize:(i,o,p)=>{assertPublicSourceReferences(p,o);assertSubset([...o.signals.map(x=>x.technology),...o.confirmedStack.map(x=>x.technology)],i.technologiesOfInterest,'technology');return o}, evidence: (ctx) => inputProof(ctx,'Las tecnologías objetivo y la empresa proceden de la entrada validada.'),
})

