defineStructuredMicroapp({id:'single-threading-detector',name:'Detector de single-threading',promise:'Mide dependencia de un único contacto y diseña una expansión de relaciones respetuosa',category:'sales',inputSchema:singleInput,outputSchema:singleOutput,uiSchema:[field('opportunity','Oportunidad','text'),field('contacts','Contactos'),field('dealStage','Etapa','text'),field('value','Valor','number'),field('requiredRoles','Roles requeridos')],followUps:[{kind:'create_multithreading_tasks',label:'Crear tareas multihilo'}],system:()=>system('Eres coach de oportunidades B2B.','{"riskLevel":"alto|medio|bajo","riskScore":0,"activeThreads":0,"missingRoles":[],"concentrationEvidence":[],"multithreadingPlan":[{"targetRole":"","introductionPath":"","messageAngle":"","priority":"alta|media|baja","successSignal":""}],"doNotBypass":[]}','Calcula el riesgo desde contactos y relaciones aportadas. No recomiendes saltarse al champion ni contactar datos personales no consentidos.'),prompt:payload,finalize:(i,o)=>{if(o.activeThreads>i.contacts.length)throw new Error('activeThreads excede los contactos aportados');assertSubset([...o.missingRoles,...o.multithreadingPlan.map(x=>x.targetRole)],i.requiredRoles,'roles');return o},evidence:(ctx)=>inputProof(ctx,'El riesgo se calcula desde el mapa de contactos aportado.'),})

