defineStructuredMicroapp({id:'explainable-close-date-predictor',name:'Predictor explicable de fecha de cierre',promise:'Estima un rango de cierre y muestra exactamente qué hitos sostienen o debilitan la previsión',category:'sales',inputSchema:closeInput,outputSchema:closeOutput,uiSchema:[field('opportunity','Oportunidad','text'),field('currentStage','Etapa','text'),field('targetCloseDate','Fecha objetivo','text'),field('stageHistory','Historial'),field('milestones','Hitos'),field('buyerCommitments','Compromisos'),field('historicalMedianDaysByStage','Medianas históricas')],followUps:[{kind:'update_forecast_review',label:'Revisar previsión'}],system:()=>system('Eres analista de forecast B2B.','{"predictedRange":{"earliest":"","mostLikely":"","latest":""},"confidence":"alta|media|baja","drivers":[{"factor":"","effect":"adelanta|retrasa|neutral","evidence":""}],"missingMilestones":[],"scenarios":[{"name":"","date":"","conditions":[]}],"notACommitment":true}','Las fechas son escenarios, nunca compromisos. Basa cada driver en historial, hitos, compromisos o medianas aportadas.'),prompt:payload,finalize:(_i,o)=>{const dates=[o.predictedRange.earliest,o.predictedRange.mostLikely,o.predictedRange.latest].map(Date.parse);if(dates.some(Number.isNaN)||!(dates[0]<=dates[1]&&dates[1]<=dates[2]))throw new Error('El rango de cierre no es cronológico');if(!o.notACommitment)throw new Error('La previsión no puede presentarse como compromiso');return o},evidence:(ctx)=>inputProof(ctx,'La previsión procede del historial, los hitos y las medianas proporcionadas.'),})

