const budgetInput=z.object({totalBudget:z.number().positive(),currency:str.max(8),channels:z.array(z.object({name:str,minSpend:z.number().nonnegative(),maxSpend:z.number().positive(),historicalCpa:z.number().positive().optional(),historicalRoas:z.number().nonnegative().optional(),confidence})).min(2).max(20),objective:z.enum(['leads','revenue','learning']),riskTolerance:z.enum(['conservadora','equilibrada','agresiva']),protectedTests:z.array(str).default([])}).superRefine((value,ctx)=>{if(value.channels.some(channel=>channel.minSpend>channel.maxSpend))ctx.addIssue({code:z.ZodIssueCode.custom,path:['channels'],message:'Cada mínimo debe ser menor o igual que su máximo'});if(value.channels.reduce((sum,channel)=>sum+channel.minSpend,0)>value.totalBudget)ctx.addIssue({code:z.ZodIssueCode.custom,path:['totalBudget'],message:'El presupuesto no cubre la suma de mínimos de canal'});if(new Set(value.channels.map(channel=>channel.name.toLocaleLowerCase())).size!==value.channels.length)ctx.addIssue({code:z.ZodIssueCode.custom,path:['channels'],message:'Los canales no pueden repetirse'})})
const budgetOutput=z.object({allocation:z.array(z.object({channel:str,amount:z.number().nonnegative(),percent:z.number().min(0).max(100),rationale:z.array(str)})),scenarios:z.array(z.object({name:str,allocationSummary:str,expectedDirection:str,risks:z.array(str)})),measurementRules:z.array(str),assumptions:z.array(str),unallocated:z.number().nonnegative()})
defineStructuredMicroapp({id:'multichannel-budget-optimizer',name:'Optimizador de presupuesto multicanal',promise:'Distribuye inversión entre canales con escenarios, supuestos y límites de riesgo visibles',category:'content',inputSchema:budgetInput,outputSchema:budgetOutput,uiSchema:[field('totalBudget','Presupuesto','number'),field('currency','Moneda','text'),field('channels','Canales'),field('objective','Objetivo','select',['leads','revenue','learning']),field('riskTolerance','Riesgo','select',['conservadora','equilibrada','agresiva']),field('protectedTests','Tests protegidos')],followUps:[{kind:'create_budget_scenario',label:'Guardar escenario'}],system:i=>system('Eres planificador de medios cuantitativo.','{"allocation":[{"channel":"","amount":0,"percent":0,"rationale":[]}],"scenarios":[{"name":"","allocationSummary":"","expectedDirection":"","risks":[]}],"measurementRules":[],"assumptions":[],"unallocated":0}',`La suma de amount más unallocated debe ser ${i.totalBudget} ${i.currency}; respeta mínimos y máximos. No inventes CPA o ROAS ausentes.`),prompt:payload,finalize:(i,o)=>{const total=o.allocation.reduce((s,x)=>s+x.amount,0)+o.unallocated;if(Math.abs(total-i.totalBudget)>0.02)throw new Error('La asignación no cuadra con el presupuesto');assertUnique(o.allocation.map(x=>x.channel),'allocation');assertSubset(o.allocation.map(x=>x.channel),i.channels.map(x=>x.name),'channels');const allocated=new Set(o.allocation.map(x=>x.channel.toLocaleLowerCase()));if(i.channels.some(channel=>channel.minSpend>0&&!allocated.has(channel.name.toLocaleLowerCase())))throw new Error('Falta un canal con inversión mínima obligatoria');for(const a of o.allocation){const c=i.channels.find(x=>x.name.toLocaleLowerCase()===a.channel.toLocaleLowerCase())!;if(a.amount<c.minSpend||a.amount>c.maxSpend)throw new Error(`Asignación fuera de límites para ${a.channel}`);const expectedPercent=a.amount/i.totalBudget*100;if(Math.abs(expectedPercent-a.percent)>.2)throw new Error(`Porcentaje incoherente para ${a.channel}`)}const pct=o.allocation.reduce((s,x)=>s+x.percent,0)+(o.unallocated/i.totalBudget*100);if(Math.abs(pct-100)>.2)throw new Error('Los porcentajes no cuadran');return o},evidence:(ctx)=>inputProof(ctx,'La asignación se limita a presupuesto, históricos y restricciones aportados.'),})

