defineStructuredMicroapp({id:'ad-account-structure-auditor',name:'Auditor de estructura publicitaria',promise:'Detecta redundancias, tracking roto y desalineación de campañas sin cambiar la cuenta',category:'content',inputSchema:adStructureInput,outputSchema:adStructureOutput,uiSchema:[field('platform','Plataforma','select',['meta','google','linkedin','tiktok','other']),field('campaigns','Campañas'),field('namingConvention','Convención','textarea'),field('businessGoal','Objetivo comercial')],followUps:[{kind:'create_ad_cleanup_plan',label:'Crear plan de limpieza'}],system:()=>system('Eres auditor de operaciones publicitarias.','{"healthScore":0,"issues":[{"campaign":"","type":"naming|overlap|objective|tracking|budget|redundancy","severity":"alta|media|baja","evidence":"","recommendation":""}],"duplicateGroups":[{"campaigns":["",""] ,"reason":""}],"trackingGaps":[],"proposedStructure":[{"level":"","name":"","purpose":""}],"safeMigrationOrder":[]}','Audita únicamente el inventario recibido. No asegures solapamiento de audiencias si no hay información suficiente; señálalo como posible.'),prompt:payload,finalize:(i,o)=>{const names=i.campaigns.map(x=>x.name);assertSubset([...o.issues.map(x=>x.campaign),...o.duplicateGroups.flatMap(x=>x.campaigns)],names,'campaigns');if(!o.safeMigrationOrder.length)throw new Error('Falta un orden de migración reversible');return o},evidence:(ctx,i)=>inputProof(ctx,`${i.campaigns.length} campañas aportadas constituyen el alcance de la auditoría.`),})

// 33 — Matriz oferta × audiencia × ángulo
const matrixInput=z.object({offers:z.array(z.object({name:str,benefit:str,proof:z.array(str)})).min(1).max(12),audiences:z.array(z.object({name:str,pains:z.array(str),awareness:z.enum(['unaware','problem','solution','product','most-aware'])})).min(1).max(20),angles:z.array(z.object({name:str,thesis:str})).min(1).max(20),maximumCells:z.number().int().min(3).max(100).default(24),constraints:z.array(str).default([])})
const matrixOutput=z.object({cells:z.array(z.object({offer:str,audience:str,angle:str,fitScore:score,hook:str,proofUsed:z.array(str),hypothesis:str,risk:str})).min(1),priorityQueue:z.array(z.object({rank:z.number().int().positive(),cellKey:str,why:str,testBudgetShare:z.number().min(0).max(100)})),coverageGaps:z.array(str)})
defineStructuredMicroapp({id:'offer-audience-angle-matrix',name:'Matriz oferta × audiencia × ángulo',promise:'Prioriza combinaciones creativas y convierte cada celda en una hipótesis publicitaria comprobable',category:'content',inputSchema:matrixInput,outputSchema:matrixOutput,uiSchema:[field('offers','Ofertas'),field('audiences','Audiencias'),field('angles','Ángulos'),field('maximumCells','Máximo de celdas','number'),field('constraints','Restricciones')],followUps:[{kind:'create_creative_experiments',label:'Crear experimentos'}],system:i=>system('Eres estratega de experimentación creativa.','{"cells":[{"offer":"","audience":"","angle":"","fitScore":0,"hook":"","proofUsed":[],"hypothesis":"","risk":""}],"priorityQueue":[{"rank":1,"cellKey":"","why":"","testBudgetShare":0}],"coverageGaps":[]}',`No superes ${i.maximumCells} celdas. Usa únicamente ofertas, audiencias, ángulos y pruebas aportadas; evita combinaciones artificiales solo para llenar la matriz.`),prompt:payload,finalize:(i,o)=>{if(o.cells.length>i.maximumCells)throw new Error('Demasiadas celdas');assertSubset(o.cells.map(x=>x.offer),i.offers.map(x=>x.name),'offers');assertSubset(o.cells.map(x=>x.audience),i.audiences.map(x=>x.name),'audiences');assertSubset(o.cells.map(x=>x.angle),i.angles.map(x=>x.name),'angles');const keys=o.cells.map(x=>`${x.offer}|${x.audience}|${x.angle}`);assertUnique(keys,'cells');assertSubset(o.priorityQueue.map(x=>x.cellKey),keys,'priorityQueue');assertUnique(o.priorityQueue.map(x=>String(x.rank)),'priority ranks');if(o.priorityQueue.some((x,n)=>x.rank!==n+1))throw new Error('La cola debe usar ranks continuos desde 1');if(Math.abs(o.priorityQueue.reduce((sum,x)=>sum+x.testBudgetShare,0)-100)>.01)throw new Error('El reparto de presupuesto de tests debe sumar 100%');for(const c of o.cells){assertSubset(c.proofUsed,i.offers.find(x=>x.name.toLocaleLowerCase()===c.offer.toLocaleLowerCase())!.proof,'proofUsed')}return o},evidence:(ctx)=>inputProof(ctx,'Todas las celdas proceden de los tres conjuntos aportados.'),})

// 34 — Biblioteca de hooks con memoria
const hookInput=z.object({brand:str,offer:str,audience:str,history:z.array(z.object({hook:str,usedAt:str,channel:str,impressions:z.number().nonnegative().optional(),result:z.number().optional(),notes:z.string().optional()})).max(1000).default([]),desiredCount:z.number().int().min(3).max(30).default(10),avoidPatterns:z.array(str).default([])})
const hookOutput=z.object({memorySummary:z.object({dominantPatterns:z.array(str),overusedPatterns:z.array(str),evidenceGaps:z.array(str)}),newHooks:z.array(z.object({hook:str,pattern:str,noveltyScore:score,similarToHistory:z.array(str),whyItFits:str,testHypothesis:str})).min(3).max(30),retire:z.array(z.object({hook:str,reason:str})),reuse:z.array(z.object({hook:str,reason:str}))})
defineStructuredMicroapp({id:'hook-memory-library',name:'Biblioteca de hooks con memoria',promise:'Aprende del historial creativo, detecta desgaste y propone hooks nuevos sin repetirse',category:'content',inputSchema:hookInput,outputSchema:hookOutput,uiSchema:[field('brand','Marca','text'),field('offer','Oferta'),field('audience','Audiencia'),field('history','Historial'),field('desiredCount','Número de hooks','number'),field('avoidPatterns','Patrones prohibidos')],followUps:[{kind:'save_hook_candidates',label:'Guardar hooks candidatos'}],system:i=>system('Eres director de copy con memoria creativa.','{"memorySummary":{"dominantPatterns":[],"overusedPatterns":[],"evidenceGaps":[]},"newHooks":[{"hook":"","pattern":"","noveltyScore":0,"similarToHistory":[],"whyItFits":"","testHypothesis":""}],"retire":[{"hook":"","reason":""}],"reuse":[{"hook":"","reason":""}]}',`Devuelve exactamente ${i.desiredCount} hooks nuevos. No atribuyas fatiga al rendimiento si faltan impresiones o resultados; separa repetición textual de desgaste demostrado.`),prompt:payload,finalize:(i,o)=>{if(o.newHooks.length!==i.desiredCount)throw new Error('Número de hooks incorrecto');assertUnique(o.newHooks.map(x=>x.hook),'newHooks');const history=i.history.map(x=>x.hook.toLocaleLowerCase());if(o.newHooks.some(x=>history.includes(x.hook.toLocaleLowerCase())))throw new Error('Un hook nuevo repite el historial');const blocked=i.avoidPatterns.map(x=>x.toLocaleLowerCase());if(o.newHooks.some(x=>blocked.some(pattern=>x.hook.toLocaleLowerCase().includes(pattern))))throw new Error('Un hook nuevo contiene un patrón prohibido');assertSubset([...o.retire.map(x=>x.hook),...o.reuse.map(x=>x.hook)],i.history.map(x=>x.hook),'history hooks');return o},evidence:(ctx,i)=>inputProof(ctx,`La memoria contiene ${i.history.length} ejecuciones creativas aportadas.`),})

// 35 — Inspector de social proof
const proofInput=z.object({claims:z.array(z.object({text:str,type:z.enum(['testimonial','metric','logo','award','case-study']),sourceUrl:publicHttpUrl.optional(),ownerApproval:z.boolean().default(false),validUntil:isoDate.optional(),territories:z.array(str).default([])})).min(1).max(200),intendedChannels:z.array(str).min(1),targetTerritories:z.array(str).min(1),requiredDisclosures:z.array(str).default([])}).superRefine((value,ctx)=>{try{assertUnique(value.claims.map(x=>x.text),'claims')}catch(error){ctx.addIssue({code:z.ZodIssueCode.custom,path:['claims'],message:(error as Error).message})}})
const proofOutput=z.object({items:z.array(z.object({claim:str,status:z.enum(['usable','needs-review','blocked']),issues:z.array(str),requiredEvidence:z.array(str),allowedChannels:z.array(str),expiryRisk:risk,safeVersion:str})),globalRisks:z.array(str),approvalQueue:z.array(z.object({claim:str,ownerAction:str,priority})),usageRules:z.array(str)})
defineStructuredMicroapp({id:'social-proof-inspector',name:'Inspector de social proof',promise:'Verifica testimonios, métricas, logos y premios antes de reutilizarlos en campañas',category:'content',inputSchema:proofInput,outputSchema:proofOutput,uiSchema:[field('claims','Pruebas'),field('intendedChannels','Canales'),field('targetTerritories','Territorios'),field('requiredDisclosures','Disclosures')],followUps:[{kind:'create_proof_approval_queue',label:'Crear cola de aprobación'}],system:()=>system('Eres revisor de evidencia comercial, no asesor legal.','{"items":[{"claim":"","status":"usable|needs-review|blocked","issues":[],"requiredEvidence":[],"allowedChannels":[],"expiryRisk":"alto|medio|bajo","safeVersion":""}],"globalRisks":[],"approvalQueue":[{"claim":"","ownerAction":"","priority":"alta|media|baja"}],"usageRules":[]}','No marques como usable una prueba sin procedencia o permiso cuando sea necesario. No prometas cumplimiento legal; deriva casos ambiguos a revisión humana.'),prompt:payload,finalize:(i,o)=>{assertSubset(o.items.map(x=>x.claim),i.claims.map(x=>x.text),'claims');assertUnique(o.items.map(x=>x.claim),'items');if(o.items.length!==i.claims.length)throw new Error('El inspector debe decidir sobre cada prueba aportada');assertSubset(o.approvalQueue.map(x=>x.claim),i.claims.map(x=>x.text),'approvalQueue');assertSubset(o.items.flatMap(x=>x.allowedChannels),i.intendedChannels,'allowedChannels');for(const item of o.items){const src=i.claims.find(x=>x.text.toLocaleLowerCase()===item.claim.toLocaleLowerCase())!;const expired=src.validUntil?src.validUntil<new Date().toISOString().slice(0,10):false;const territoryCoverage=i.targetTerritories.every(territory=>src.territories.some(allowed=>allowed.toLocaleLowerCase()===territory.toLocaleLowerCase()));if(item.status==='usable'&&(!src.sourceUrl||!src.ownerApproval||expired||!territoryCoverage))throw new Error('No se puede marcar usable sin fuente, aprobación, vigencia y cobertura territorial')}return o},evidence:(ctx,i)=>inputProof(ctx,`${i.claims.length} pruebas aportadas fueron inspeccionadas; el resultado no sustituye revisión jurídica.`),})

