defineStructuredMicroapp({id:'pricing-page-optimizer',name:'Optimizador de página de precios',promise:'Rediseña jerarquía, anclaje, planes, FAQ y experimentos sin inventar valor demostrado',category:'content',inputSchema:pricingInput,outputSchema:pricingOutput,uiSchema:[field('plans','Planes'),field('conversionGoal','Conversión','select',['trial','demo','purchase']),field('objections','Objeciones'),field('availableProof','Pruebas'),field('constraints','Restricciones')],followUps:[{kind:'create_pricing_page_brief',label:'Crear briefing de precios'}],system:()=>system('Eres especialista CRO y monetización.','{"diagnosis":[{"issue":"","impact":"alta|media|baja","evidenceFromInput":""}],"recommendedArchitecture":[{"section":"","purpose":"","content":""}],"planReframing":[{"plan":"","positioning":"","recommendedFor":"","cta":""}],"faq":[{"question":"","answer":"","proofUsed":null}],"experiments":[{"hypothesis":"","change":"","metric":"","guardrail":""}],"claimsNeedingProof":[]}','No cambies precios ni límites fuera de los declarados; cualquier propuesta debe marcarse como experimento. Usa solo pruebas disponibles.'),prompt:payload,finalize:(i,o)=>{assertSubset(o.planReframing.map(x=>x.plan),i.plans.map(x=>x.name),'plans');assertSubset(o.faq.flatMap(x=>x.proofUsed?[x.proofUsed]:[]),i.availableProof,'proofUsed');return o},evidence:(ctx)=>inputProof(ctx,'El diagnóstico se limita a planes, objeciones y pruebas aportados.'),})

