const magnetOutput=z.object({concept:z.object({title:str,promise:str,qualificationMechanism:str}),outline:z.array(z.object({section:str,purpose:str,keyPoints:z.array(str)})).min(3),assetRequirements:z.array(str),landing:z.object({headline:str,subheadline:str,bullets:z.array(str),formFields:z.array(str),cta:str}),deliverySequence:z.array(z.object({delay:str,subject:str,messageGoal:str,cta:str})).min(2),promotionAngles:z.array(z.object({angle:str,hook:str,channel:str})),handoffToOffer:str})
defineStructuredMicroapp({id:'lead-magnet-designer',name:'Diseñador de lead magnet',promise:'Crea el concepto, contenido, landing, entrega y promoción de un activo de captación',category:'content',inputSchema:magnetInput,outputSchema:magnetOutput,uiSchema:[field('audience','Audiencia'),field('problem','Problema'),field('offer','Oferta'),field('format','Formato','select',['guide','checklist','calculator','template','assessment']),field('expertInputs','Conocimiento experto'),field('conversionGoal','Conversión'),field('brandConstraints','Restricciones')],followUps:[{kind:'create_lead_magnet_project',label:'Crear proyecto de lead magnet'}],system:()=>system('Eres arquitecto de demanda B2B.','{"concept":{"title":"","promise":"","qualificationMechanism":""},"outline":[{"section":"","purpose":"","keyPoints":[]}],"assetRequirements":[],"landing":{"headline":"","subheadline":"","bullets":[],"formFields":[],"cta":""},"deliverySequence":[{"delay":"","subject":"","messageGoal":"","cta":""}],"promotionAngles":[{"angle":"","hook":"","channel":""}],"handoffToOffer":""}','El activo debe resolver parte del problema y calificar interés sin ocultar su propósito. No inventes conocimiento experto ausente.'),prompt:payload,finalize:(_i,o)=>{assertUnique(o.outline.map(x=>x.section),'outline sections');if(!o.landing.formFields.length)throw new Error('La landing necesita un formulario explícito');if(!o.deliverySequence.every(x=>x.cta.trim()))throw new Error('Cada entrega necesita CTA');return o},evidence:(ctx)=>inputProof(ctx,'El diseño parte del problema, oferta y conocimiento experto aportados.'),})

