const retargetInput=z.object({journeyStages:z.array(z.object({name:str,audienceDefinition:str,estimatedSize:z.number().nonnegative().optional(),intentSignals:z.array(str)})).min(2).max(12),channels:z.array(str).min(1).max(10),offer:str,conversionWindowDays:z.number().int().min(1).max(180),exclusions:z.array(str).default([]),frequencyLimits:z.record(z.number().positive()).default({})})
const retargetOutput=z.object({segments:z.array(z.object({stage:str,inclusion:str,exclusions:z.array(str),windowDays:z.number().int().positive(),message:str,cta:str,channels:z.array(str),frequencyRule:str})),sequence:z.array(z.object({dayRange:str,segment:str,creativeGoal:str,proof:str,stopCondition:str})),suppressionRules:z.array(str),measurement:z.object({primaryEvents:z.array(str),incrementalityTest:str,guardrails:z.array(str)}),privacyChecks:z.array(str)})
defineStructuredMicroapp({id:'retargeting-planner',name:'Planificador de retargeting',promise:'Diseña ventanas, exclusiones, mensajes y secuencia de retargeting según intención',category:'content',inputSchema:retargetInput,outputSchema:retargetOutput,uiSchema:[field('journeyStages','Etapas'),field('channels','Canales'),field('offer','Oferta'),field('conversionWindowDays','Ventana','number'),field('exclusions','Exclusiones'),field('frequencyLimits','Límites de frecuencia')],followUps:[{kind:'create_retargeting_brief',label:'Crear briefing de retargeting'}],system:i=>system('Eres estratega de medios de ciclo completo.','{"segments":[{"stage":"","inclusion":"","exclusions":[],"windowDays":1,"message":"","cta":"","channels":[],"frequencyRule":""}],"sequence":[{"dayRange":"","segment":"","creativeGoal":"","proof":"","stopCondition":""}],"suppressionRules":[],"measurement":{"primaryEvents":[],"incrementalityTest":"","guardrails":[]},"privacyChecks":[]}',`Ninguna ventana puede superar ${i.conversionWindowDays} días. Respeta exclusiones, consentimiento y límites de frecuencia; no asumas tamaños ausentes.`),prompt:payload,finalize:(i,o)=>{assertSubset(o.segments.map(x=>x.stage),i.journeyStages.map(x=>x.name),'stages');assertSubset(o.segments.flatMap(x=>x.channels),i.channels,'channels');if(o.segments.some(x=>x.windowDays>i.conversionWindowDays))throw new Error('Ventana de retargeting fuera del máximo');if(!o.privacyChecks.length)throw new Error('Faltan controles de privacidad');return o},evidence:(ctx)=>inputProof(ctx,'La segmentación usa únicamente etapas, señales y exclusiones aportadas.'),})

// 39 — Biblioteca de claims y evidencias
const claimsInput=z.object({claims:z.array(z.object({id:str,text:str,source:str,sourceType:z.enum(['study','customer-data','testimonial','certification','internal-analysis']),verifiedAt:isoDate.optional(),validUntil:isoDate.optional(),territories:z.array(str).default([]),channels:z.array(str).default([]),owner:str})).min(1).max(1000),requestedChannels:z.array(str).min(1),requestedTerritories:z.array(str).min(1),asOfDate:isoDate}).superRefine((value,ctx)=>{try{assertUnique(value.claims.map(x=>x.id),'claim ids')}catch(error){ctx.addIssue({code:z.ZodIssueCode.custom,path:['claims'],message:(error as Error).message})}})
const claimsOutput=z.object({library:z.array(z.object({id:str,status:z.enum(['approved','expired','restricted','unverified']),reason:str,allowedChannels:z.array(str),allowedTerritories:z.array(str),expiryAction:z.string().nullable(),safeClaim:str})),conflicts:z.array(z.object({claimIds:z.array(str).min(2),issue:str,resolution:str})),missingEvidence:z.array(z.object({claimId:str,needed:str,owner:str})),governanceRules:z.array(str)})
defineStructuredMicroapp({id:'claims-evidence-library',name:'Biblioteca de claims y evidencias',promise:'Relaciona cada promesa con su fuente, vigencia, propietario y usos autorizados',category:'data',inputSchema:claimsInput,outputSchema:claimsOutput,uiSchema:[field('claims','Claims'),field('requestedChannels','Canales'),field('requestedTerritories','Territorios'),field('asOfDate','Fecha de revisión','text')],followUps:[{kind:'save_claims_governance',label:'Guardar reglas de claims'}],system:()=>system('Eres responsable de gobernanza de claims.','{"library":[{"id":"","status":"approved|expired|restricted|unverified","reason":"","allowedChannels":[],"allowedTerritories":[],"expiryAction":null,"safeClaim":""}],"conflicts":[{"claimIds":["",""] ,"issue":"","resolution":""}],"missingEvidence":[{"claimId":"","needed":"","owner":""}],"governanceRules":[]}','Evalúa cada claim a la fecha indicada. No apruebes una fuente por su nombre: exige verificación y vigencia explícitas. Esto es triage, no dictamen legal.'),prompt:payload,finalize:(i,o)=>{const ids=i.claims.map(x=>x.id);assertSubset([...o.library.map(x=>x.id),...o.conflicts.flatMap(x=>x.claimIds),...o.missingEvidence.map(x=>x.claimId)],ids,'claim ids');assertUnique(o.library.map(x=>x.id),'library');if(o.library.length!==ids.length)throw new Error('La biblioteca debe decidir sobre cada claim aportado');for(const row of o.library){const claim=i.claims.find(x=>x.id===row.id)!;const requestedChannels=new Set(i.requestedChannels.map(x=>x.toLocaleLowerCase()));const requestedTerritories=new Set(i.requestedTerritories.map(x=>x.toLocaleLowerCase()));const channelIntersection=claim.channels.filter(x=>requestedChannels.has(x.toLocaleLowerCase()));const territoryIntersection=claim.territories.filter(x=>requestedTerritories.has(x.toLocaleLowerCase()));assertSubset(row.allowedChannels,channelIntersection,'allowedChannels');assertSubset(row.allowedTerritories,territoryIntersection,'allowedTerritories');const expired=claim.validUntil?claim.validUntil<i.asOfDate:false;const verifiedInTime=Boolean(claim.verifiedAt&&claim.verifiedAt<=i.asOfDate);if(expired&&row.status!=='expired')throw new Error('Un claim vencido debe marcarse expired');if(row.status==='approved'&&(!verifiedInTime||!claim.source||expired))throw new Error('Claim aprobado sin verificación vigente')}return o},evidence:(ctx,i)=>inputProof(ctx,`${i.claims.length} claims y sus metadatos constituyen el registro auditado.`),})

