defineStructuredMicroapp({id:'brand-voice-compiler',name:'Compilador de voz de marca',promise:'Convierte ejemplos aprobados y rechazados en reglas medibles, léxico y tests de consistencia',category:'content',inputSchema:voiceInput,outputSchema:voiceOutput,uiSchema:[field('brand','Marca','text'),field('approvedExamples','Ejemplos aprobados'),field('rejectedExamples','Ejemplos rechazados'),field('audiences','Audiencias'),field('channels','Canales'),field('existingRules','Reglas existentes')],followUps:[{kind:'save_brand_voice_profile',label:'Guardar perfil de voz'}],system:()=>system('Eres lingüista computacional de marca.','{"voicePrinciples":[{"principle":"","evidenceFromExamples":[],"do":[],"dont":[]}],"lexicon":{"preferred":[{"term":"","useWhen":""}],"avoided":[{"term":"","reason":""}],"signaturePhrases":[]},"channelAdjustments":[{"channel":"","keep":"","adapt":"","example":""}],"audienceAdjustments":[{"audience":"","adaptation":"","guardrail":""}],"lintRules":[{"ruleId":"","description":"","severity":"alta|media|baja","testExample":""}],"validationSet":[{"text":"","expected":"pass|fail","reason":""}]}','Deriva cada principio de ejemplos aportados. Las frases firma son patrones, no citas inventadas. Crea tests positivos y negativos.'),prompt:payload,finalize:(i,o)=>{assertSubset(o.channelAdjustments.map(x=>x.channel),i.channels,'channels');assertSubset(o.audienceAdjustments.map(x=>x.audience),i.audiences,'audiences');assertUnique(o.lintRules.map(x=>x.ruleId),'lintRules');if(!o.validationSet.some(x=>x.expected==='pass')||!o.validationSet.some(x=>x.expected==='fail'))throw new Error('El set de validación necesita casos positivos y negativos');return o},evidence:(ctx,i)=>inputProof(ctx,`${i.approvedExamples.length} ejemplos aprobados y ${i.rejectedExamples.length} rechazados sostienen las reglas.`),})

